<template>
  <main class="contact-page" :dir="isRtl ? 'rtl' : 'ltr'" :data-theme="theme">
    <section class="contact-shell">
      <aside class="agent-summary">
        <button class="back" @click="router.back()"><i class="fa-solid fa-arrow-left"></i> {{ t('Back', 'رجوع') }}</button>
        <div class="agent-avatar"><img src="/images/photo-1507003211169-0a1dd7228f2d.jfif" alt="Daniel Matthews"></div>
        <h1>{{ t('Daniel Matthews', 'دانيال ماثيوز') }}</h1>
        <p>{{ t('Premium Property Specialist', 'أخصائي عقارات مميزة') }}</p>
        <span class="online"><i></i>{{ t('Online now', 'متصل الآن') }}</span>
        <div v-if="property" class="property-context"><img :src="property.image"><div><small>{{ t('Regarding property', 'بخصوص العقار') }}</small><b>{{ title }}</b></div></div>
        <button class="call" @click="startCall"><i class="fa-solid fa-phone"></i>{{ t('Start a call', 'بدء مكالمة') }}</button>
      </aside>
      <section class="chat-panel">
        <header><div><b>{{ t('Chat with Daniel', 'محادثة مع دانيال') }}</b><span>{{ t('Usually replies within minutes', 'يرد عادة خلال دقائق') }}</span></div><button @click="startCall" :aria-label="t('Call', 'اتصال')"><i class="fa-solid fa-phone"></i></button></header>
        <div ref="messagesEl" class="messages"><div v-for="message in messages" :key="message.id" class="message" :class="message.from"><p>{{ message.text }}</p><time>{{ message.time }}</time></div></div>
        <div v-if="callActive" class="call-banner"><i class="fa-solid fa-phone-volume"></i><span>{{ t('Call in progress with Daniel Matthews', 'مكالمة جارية مع دانيال ماثيوز') }}</span><button @click="callActive=false"><i class="fa-solid fa-phone-slash"></i>{{ t('End call', 'إنهاء المكالمة') }}</button></div>
        <form class="composer" @submit.prevent="sendMessage"><input v-model="draft" :placeholder="t('Write a message…', 'اكتب رسالتك…')"><button type="button" @click="attachFile"><i class="fa-solid fa-paperclip"></i></button><button class="send" :disabled="!draft.trim()"><i class="fa-solid fa-paper-plane"></i></button></form>
      </section>
    </section>
  </main>
</template>

<script setup>
import { computed, nextTick, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useThemeAndLanguage } from '../composables/useThemeAndLanguage'
import propertyService from '../services/propertyService'
const router = useRouter(); const route = useRoute(); const { isRtl, theme } = useThemeAndLanguage(); const t = (en, ar) => isRtl.value ? ar : en
const property = ref(null); try { property.value = JSON.parse(sessionStorage.getItem('vibelocate:selected-property') || 'null') } catch {}
const title = computed(() => isRtl.value ? property.value?.title_ar || property.value?.title : property.value?.title)
const messagesEl = ref(null), draft = ref(''), callActive = ref(false)
callActive.value = route.query.mode === 'call'
const messages = ref([{ id: 1, from: 'agent', text: t('Hello! How can I help you with this property?', 'مرحباً! كيف يمكنني مساعدتك بخصوص هذا العقار؟'), time: '10:24' }])
const scroll = async () => { await nextTick(); messagesEl.value?.scrollTo({ top: messagesEl.value.scrollHeight, behavior: 'smooth' }) }
const sendMessage = async () => { const text = draft.value.trim(); if (!text) return; messages.value.push({ id: Date.now(), from: 'user', text, time: new Date().toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' }) }); draft.value=''; scroll(); if (property.value?.id) { try { await propertyService.submitInquiry(property.value.id, { message: text }); } catch (e) { console.warn('Inquiry API failed:', e) } } setTimeout(() => { messages.value.push({ id: Date.now()+1, from:'agent', text:t('Thank you. I will get back to you shortly.', 'شكراً لك، سأرد عليك قريباً.'), time:new Date().toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' }) }); scroll() }, 700) }
const startCall = () => { callActive.value = true }
const attachFile = () => { messages.value.push({ id: Date.now(), from:'user', text:t('Attachment shared', 'تمت مشاركة مرفق'), time:new Date().toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' }) }); scroll() }
</script>

<style scoped>
.contact-page{--bg:#f4f8fc;--surface:#fff;--text:#10253f;--muted:#6a7d90;--border:#d7e4ef;--accent:#087ff5;min-height:calc(100vh - 76px);background:var(--bg);padding:34px 20px;font-family:'Plus Jakarta Sans',sans-serif}.contact-shell{max-width:1050px;min-height:620px;margin:auto;display:grid;grid-template-columns:300px 1fr;background:var(--surface);border:1px solid var(--border);border-radius:22px;overflow:hidden;box-shadow:0 18px 45px rgba(27,69,103,.1)}.agent-summary{padding:28px;text-align:center;background:linear-gradient(165deg,#eef8ff,#fff 65%);border-inline-end:1px solid var(--border)}.back{background:none;border:0;color:var(--accent);font:inherit;cursor:pointer;float:inline-start}.agent-avatar{margin:54px auto 16px;width:104px;height:104px;border-radius:50%;padding:4px;background:linear-gradient(135deg,#12cde8,#087ff5)}.agent-avatar img{width:100%;height:100%;object-fit:cover;border-radius:50%;border:4px solid #fff}.agent-summary h1{font-size:20px;color:var(--text);margin:0}.agent-summary p{font-size:13px;color:var(--muted);margin:7px 0}.online{display:inline-flex;gap:7px;align-items:center;padding:6px 10px;background:#e9fbf5;color:#078863;border-radius:99px;font-size:12px}.online i{width:7px;height:7px;border-radius:50%;background:#16c98d}.property-context{display:flex;gap:10px;text-align:start;margin:28px 0;padding:10px;background:#fff;border:1px solid var(--border);border-radius:12px}.property-context img{width:46px;height:46px;border-radius:8px;object-fit:cover}.property-context small,.property-context b{display:block}.property-context small{font-size:10px;color:var(--muted)}.property-context b{font-size:11px;color:var(--text);margin-top:3px}.call,.send{border:0;background:linear-gradient(135deg,#087ff5,#0868ed);color:#fff;border-radius:10px;font-weight:700;cursor:pointer}.call{width:100%;height:43px}.call i{margin-inline-end:8px}.chat-panel{min-width:0;display:flex;flex-direction:column}.chat-panel header{height:82px;padding:0 24px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--border)}.chat-panel header b{display:block;color:var(--text)}.chat-panel header span{display:block;color:var(--muted);font-size:12px;margin-top:4px}.chat-panel header button{width:38px;height:38px;border:0;border-radius:50%;background:#eaf5ff;color:var(--accent);cursor:pointer}.messages{flex:1;min-height:390px;max-height:520px;overflow:auto;padding:24px;background:#fbfdff;display:flex;flex-direction:column;gap:14px}.message{max-width:72%;padding:11px 13px;border-radius:14px;background:#edf4fa;color:var(--text);align-self:flex-start}.message.user{align-self:flex-end;background:linear-gradient(135deg,#087ff5,#1b83ef);color:#fff}.message p{margin:0;line-height:1.45;font-size:14px}.message time{display:block;font-size:10px;opacity:.7;margin-top:5px}.call-banner{margin:0 20px 10px;padding:10px 12px;display:flex;align-items:center;gap:9px;border-radius:10px;background:#eaf7ff;color:#0875bd;font-size:12px}.call-banner button{margin-inline-start:auto;border:0;background:#feecec;color:#d63636;padding:7px 9px;border-radius:7px;cursor:pointer}.composer{padding:16px;display:flex;gap:8px;border-top:1px solid var(--border)}.composer input{flex:1;min-width:0;border:1px solid var(--border);border-radius:11px;padding:0 13px;font:inherit;outline-color:var(--accent)}.composer button{width:42px;border:1px solid var(--border);background:#fff;border-radius:10px;color:var(--muted);cursor:pointer}.composer .send{border:0;color:#fff}.composer .send:disabled{opacity:.45;cursor:not-allowed}.contact-page[data-theme="dark"]{--bg:#0f172a;--surface:#1e293b;--text:#f8fafc;--muted:#94a3b8;--border:#334155;--accent:#38bdf8}.contact-page[data-theme="dark"] .agent-summary{background:linear-gradient(165deg,#1e293b,#162235 65%)}.contact-page[data-theme="dark"] .property-context,.contact-page[data-theme="dark"] .composer button{background:#162235;border-color:#334155}.contact-page[data-theme="dark"] .messages{background:#0f172a}.contact-page[data-theme="dark"] .message{background:#1e293b;color:#f8fafc}.contact-page[data-theme="dark"] .composer input{background:#162235;border-color:#334155;color:#f8fafc}@media(max-width:700px){.contact-page{padding:0}.contact-shell{min-height:calc(100vh - 76px);border-radius:0;grid-template-columns:1fr}.agent-summary{display:none}.messages{min-height:calc(100vh - 240px)}}
</style>
